mapper.select:
      select a.money1,b.money2,c.money3,d.money4,e.money5,f.money6,g.money7,h.money8,i.money9,j.money10,k.money11,l.money12 from (SELECT SUM(IFNULL(money1,0)) money1,1 type FROM (

SELECT
SUM(
IFNULL( r.medical_history_money, 0 )+ IFNULL( r.other_money, 0 )+ IFNULL( r.troubleshooting_money, 0 )+ IFNULL(r.opc_troubleshooting_money,0) + IFNULL(r.printing_money,0) + IFNULL(r.cross_driving_money,0) + IFNULL(r.self_driving_money,0) + IFNULL(r.cityin_driving_money,0) + IFNULL(r.accommodatio_money,0)
)  money1
FROM
survey_clock_re_info r
LEFT JOIN survey_user_clock u ON r.clock_id = u.id
LEFT JOIN staff_personnel_info i ON u.survey_user_id = i.user_id
WHERE
DATE_FORMAT( r.create_time, '%Y-%m' ) = #{date1}

  AND i.organ_id = #{orgId}

UNION ALL

SELECT SUM(IFNULL(real_wages,0)+IFNULL(company_money_sub,0)) money1 FROM staff_pay_personnel_slip WHERE delete_flag = 0 AND DATE_FORMAT( create_time, '%Y-%m' ) = #{date1}

  AND organ_id = #{orgId}


UNION ALL
/**绩效*/
SELECT SUM(IFNULL(fixed_perf_pay,0)+IFNULL(travel_allowance_pay,0)+IFNULL(manage_perf_pay,0)+IFNULL(real_assess_kpi,0)+IFNULL(integral_pay,0)+IFNULL(examine_pay,0)+IFNULL( late_early_money,0)+IFNULL(absenteeism_money,0)+IFNULL(leave_money,0)+IFNULL(sick_leave_money,0)+IFNULL(other_pay,0)+IFNULL( other_cut_pay,0)) money1 FROM staff_performance_personnel  WHERE delete_flag = 0 AND DATE_FORMAT( create_time, '%Y-%m' ) = #{date1}

  AND organ_id = #{orgId}


UNION ALL


