LEFT JOIN staff_personnel_info i ON c.survey_user_id = i.user_id
WHERE c.delete_flag = 0 AND DATE_FORMAT( c.operation_time, '%Y-%m' ) = #{date1}

  AND i.organ_id = #{orgId}


UNION ALL


